import json,sys
ST="draft_pending_book_check"
topics=[]
def T(tid,title,expl,examples,questions,src):
    exs=[];qs=[]
    for i,e in enumerate(examples,1):
        ref,ex,focus,rule,why=e
        exs.append({"id":f"{tid}.POOL99.E{i}","topicId":tid,"verseRef":ref,"excerptAr":ex,"focus":focus,"rule":rule,"explanation":why,"verification":"uthmani_text_checked_2026-11-27; book_checked_2026-11-27"})
    for i,q in enumerate(questions,1):
        kind=q[0]; d={"id":f"{tid}.POOL99.Q{i}","topicId":tid,"objective":q[-2],"difficulty":q[-1],"variantFamily":f"review99-{tid}","status":ST}
        if kind=="tf":
            _,text,ans,fb,_o,_d=q; d.update(type="trueFalse",text=text,correctAnswer=ans,feedbackAr=fb)
        elif kind in("sc","mc"):
            _,text,opts,correct,fb,*rest=q
            ex=None
            if isinstance(text,tuple): text,ex=text
            d.update(type="singleChoice" if kind=="sc" else "multipleChoice",text=text,options=[{"id":str(j+1),"text":o} for j,o in enumerate(opts)],
                     correctAnswer=str(correct+1) if kind=="sc" else [str(c+1) for c in correct],feedbackAr=fb)
            if ex: d["exampleId"]=f"{tid}.POOL99.E{ex}"
        qs.append(d)
    topics.append({"topicId":tid,"titleAr":title,"source":src,"explanationAr":expl,"examples":exs,"questions":qs})

# 1. Ra
